'use client';
import { useRef, useState, useEffect } from 'react';
import type { Project } from '@/lib/projects';
import { Carousel } from './Carousel';

export function ProjectCard({ project, isExpanded, onToggle }: { project: Project; isExpanded: boolean; onToggle: () => void; }) {
  const imageItems = project.media.filter((m) => m.type === 'image');
  const glbItems = project.media.filter((m) => m.type === 'glb');
  const coverImage = imageItems[0];

  return (
    <div style={{ background: 'var(--white)', position: 'relative', zIndex: 1 }}>
      {/* Header row — click to expand */}
      <div
        onClick={onToggle}
        data-hover
        style={{
          display: 'grid',
          gridTemplateColumns: '280px 1fr auto',
          alignItems: 'stretch',
          cursor: 'pointer',
          minHeight: '280px',
          gap: 0,
        }}
      >
        {/* Cover image */}
        <div className="img-hover-frame" style={{ height: '100%', minHeight: 280, overflow: 'hidden', position: 'relative' }}>
          <div style={{ width: '100%', height: '100%', minHeight: 280, overflow: 'hidden' }}>
            {coverImage ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={coverImage.src} alt={coverImage.alt}
                style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', filter: 'grayscale(100%)', transition: 'filter 0.4s ease, transform 0.5s ease' }}
                onError={(e) => ((e.currentTarget as HTMLImageElement).style.opacity = '0')}
              />
            ) : (
              <div style={{ width: '100%', height: '100%', background: 'var(--gray-50)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: '2rem', color: 'var(--gray-200)' }}>□</span>
              </div>
            )}
          </div>
        </div>

        {/* Info */}
        <div style={{ padding: '2rem 2.5rem', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', borderLeft: '1px solid var(--black)' }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1rem' }}>
              <span className="label">{project.semester}</span>
              {project.tags.map((t) => (
                <span key={t} style={{ fontFamily: 'var(--font-mono)', fontSize: '0.55rem', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--gray-500)', border: '1px solid var(--gray-300)', padding: '0.1rem 0.4rem' }}>{t}</span>
              ))}
              {glbItems.length > 0 && (
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.55rem', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--white)', background: 'var(--black)', padding: '0.1rem 0.4rem' }}>3D ×</span>
              )}
            </div>

            <h3 style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 'clamp(1.4rem,2.5vw,2.5rem)', letterSpacing: '-0.03em', lineHeight: 1.05, marginBottom: '1rem', textTransform: 'uppercase' }}>
              {project.title}
            </h3>

            <p style={{ fontFamily: 'var(--font-mono)', fontWeight: 300, fontSize: '0.75rem', lineHeight: 1.7, color: 'var(--gray-700)', maxWidth: '400px' }}>
              {project.description}
            </p>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginTop: '1.5rem' }}>
            <span className="label">{imageItems.length} images</span>
            {glbItems.length > 0 && <span className="label">+ {glbItems.length} model</span>}
          </div>
        </div>

        {/* Toggle button */}
        <div style={{
          width: '60px', borderLeft: '1px solid var(--black)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          background: isExpanded ? 'var(--black)' : 'transparent',
          transition: 'background 0.2s ease',
          flexShrink: 0,
        }}>
          <span style={{
            fontFamily: 'var(--font-mono)', fontSize: '1.2rem',
            color: isExpanded ? 'var(--white)' : 'var(--black)',
            transform: isExpanded ? 'rotate(45deg)' : 'none',
            transition: 'transform 0.3s ease, color 0.2s ease',
            display: 'block', lineHeight: 1,
          }}>
            ×
          </span>
        </div>
      </div>

      {/* Expanded content */}
      <div style={{
        overflow: 'hidden',
        maxHeight: isExpanded ? '2000px' : '0',
        transition: 'max-height 0.7s cubic-bezier(0.16,1,0.3,1)',
        borderTop: isExpanded ? '1px solid var(--black)' : 'none',
      }}>
        <div style={{ padding: '3rem', background: 'var(--off-white)', display: 'grid', gridTemplateColumns: glbItems.length > 0 ? '1.4fr 1fr' : '1fr', gap: '3rem' }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem' }}>
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.9rem', color: 'var(--gray-300)' }}>○</span>
              <span className="label">Documentation — {imageItems.length} images</span>
            </div>
            <Carousel items={project.media} projectTitle={project.title} />
          </div>

          {glbItems.length > 0 && (
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem' }}>
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.9rem', color: 'var(--gray-300)' }}>□</span>
                <span className="label">3D Model — Interactive</span>
              </div>
              <GlbLazy src={glbItems[0].src} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function GlbLazy({ src }: { src: string }) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => { const t = setTimeout(() => setMounted(true), 300); return () => clearTimeout(t); }, []);
  if (!mounted) return (
    <div style={{ height: 360, background: 'var(--black)', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid var(--black)' }}>
      <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', color: 'var(--gray-500)', letterSpacing: '0.15em', textTransform: 'uppercase' }}>loading model...</span>
    </div>
  );
  const { GlbViewer } = require('./GlbViewer');
  return <GlbViewer src={src} height={360} />;
}
